// Wide-bus helper: read `count` floating-point elements from a 512-bit
// AXI bus into a local array, starting at byte offset `offset`.
template <typename T, int W>
static void memcpy_wide_bus_read_float(T* local, ap_uint<W>* bus,
                                       long offset_bytes, int count) {
    const int elems_per_word = W / (sizeof(T) * 8);
    long start_elem = offset_bytes / (long)sizeof(T);
    int idx = 0;
RD_OUTER:
    while (idx < count) {
        long global_elem = start_elem + idx;
        long word_idx = global_elem / elems_per_word;
        int word_off = (int)(global_elem % elems_per_word);
        ap_uint<W> word = bus[word_idx];
    RD_INNER:
        for (int e = word_off; e < elems_per_word && idx < count; e++) {
#pragma HLS PIPELINE II=1
            ap_uint<sizeof(T) * 8> raw =
                word.range((e + 1) * sizeof(T) * 8 - 1, e * sizeof(T) * 8);
            T val;
            std::memcpy(&val, &raw, sizeof(T));
            local[idx] = val;
            idx++;
        }
    }
}

// Wide-bus helper: write `count` floating-point elements from a local array
// to a 512-bit AXI bus, starting at byte offset `offset`.
template <typename T, int W>
static void memcpy_wide_bus_write_float(T* local, ap_uint<W>* bus,
                                        long offset_bytes, int count) {
    const int elems_per_word = W / (sizeof(T) * 8);
    long start_elem = offset_bytes / (long)sizeof(T);
    int idx = 0;
WR_OUTER:
    while (idx < count) {
        long global_elem = start_elem + idx;
        long word_idx = global_elem / elems_per_word;
        int word_off = (int)(global_elem % elems_per_word);
        ap_uint<W> word = bus[word_idx];
    WR_INNER:
        for (int e = word_off; e < elems_per_word && idx < count; e++) {
#pragma HLS PIPELINE II=1
            T val = local[idx];
            ap_uint<sizeof(T) * 8> raw;
            std::memcpy(&raw, &val, sizeof(T));
            word.range((e + 1) * sizeof(T) * 8 - 1, e * sizeof(T) * 8) = raw;
